const prepare = function ({ results }) {
  if (!Array.isArray(results) || results.length > 5) throw new Error('Expected at most five Tavily search results.');
  return { results: results.map(result => {
    if (!result || typeof result !== 'object' || Array.isArray(result) || typeof result.title !== 'string' || typeof result.url !== 'string' || typeof result.content !== 'string') throw new Error('A search result is missing its title, URL or snippet.');
    return { title: result.title, url: result.url, snippet: result.content };
  }) };
}

return $input.all().flatMap((item,index)=>prepare({results:item.json.results}).results.map(json=>({json,pairedItem:{item:index}})));

const prepare = function ({ query }) {
  if (typeof query !== 'string' || !query.trim()) throw new Error('Enter a nonempty search query.');
  return { query: query.trim() };
}

return $input.all().map((item,index)=>({json:prepare(item.json),pairedItem:{item:index}}));
